css:
.chat {
  {{width}}: 320px;
  {{border}}: 1px solid #eee;
  {{border-radius}}: 14px;
  {{overflow}}: hidden;
  {{font-family}}: sans-serif;
}
.bar {
  {{display}}: flex;
  {{align-items}}: center;
  {{gap}}: 10px;
  {{padding}}: 10px 12px;
  {{background}}: #f97316;
  {{color}}: white;
}
.avatar {
  {{width}}: 36px;
  {{height}}: 36px;
  {{border-radius}}: 50%;
  {{background}}: #ffe8d6;
  {{color}}: #f97316;
  {{font-weight}}: 700;
  {{text-align}}: center;
  {{line-height}}: 36px;
}
.who { {{display}}: flex; flex-direction: column; }
.status { {{font-size}}: 12px; opacity: 0.85; }
.thread {
  {{display}}: flex;
  {{flex-direction}}: column;
  {{gap}}: 8px;
  {{padding}}: 12px;
  {{background}}: #fafafa;
}
.msg {
  {{max-width}}: 75%;
  {{padding}}: 8px 12px;
  {{font-size}}: 14px;
}
.in {
  {{align-self}}: flex-start;
  {{background}}: #eee;
  {{border-radius}}: 14px 14px 14px 2px;
}
.out {
  {{align-self}}: flex-end;
  {{background}}: #f97316;
  {{color}}: white;
  {{border-radius}}: 14px 14px 2px 14px;
}
.compose {
  {{display}}: flex;
  {{gap}}: 8px;
  {{padding}}: 10px;
}
.compose input {
  {{flex}}: 1;
  {{border}}: 1px solid #ddd;
  {{border-radius}}: 999px;
  {{padding}}: 8px 14px;
}
.compose button {
  {{border}}: none;
  {{border-radius}}: 999px;
  {{background}}: #f97316;
  {{color}}: white;
  {{padding}}: 8px 16px;
  {{cursor}}: pointer;
}

.reel {
  {{position}}: relative;
  {{width}}: 220px;
  {{aspect-ratio}}: 9 / 16;
  {{border-radius}}: 16px;
  {{overflow}}: hidden;
  {{background}}: linear-gradient(160deg, #fbbf24, #f97316);
  {{font-family}}: sans-serif;
  {{color}}: white;
}
.scrim {
  {{position}}: absolute;
  {{inset}}: 0;
  {{background}}: linear-gradient(to top, rgba(0,0,0,0.55), transparent 45%);
}
.rail {
  {{position}}: absolute;
  {{right}}: 10px;
  {{bottom}}: 70px;
  {{display}}: flex;
  {{flex-direction}}: column;
  {{gap}}: 14px;
  {{z-index}}: 2;
}
.act {
  {{width}}: 40px;
  {{height}}: 40px;
  {{border-radius}}: 50%;
  {{background}}: rgba(255,255,255,0.25);
  {{text-align}}: center;
  {{line-height}}: 40px;
  {{font-weight}}: 700;
}
.caption {
  {{position}}: absolute;
  {{left}}: 12px;
  {{bottom}}: 14px;
  {{z-index}}: 2;
  {{max-width}}: 150px;
}
.caption p { {{margin}}: 4px 0 0; font-size: 13px; }

.app {
  {{display}}: grid;
  {{grid-template-columns}}: 180px 1fr;
  {{gap}}: 16px;
  {{max-width}}: 560px;
  {{font-family}}: sans-serif;
  {{color}}: #222;
}
.side { {{background}}: #f4f4f4; border-radius: 12px; padding: 12px; }
.side h4 { {{margin}}: 0 0 8px; }
.side ul { {{list-style}}: none; margin: 0; padding: 0; }
.side li { {{padding}}: 6px 8px; border-radius: 6px; font-size: 14px; color: #666; }
.side .active { {{background}}: #f97316; color: white; font-weight: 600; }
.video {
  {{aspect-ratio}}: 16 / 9;
  {{display}}: flex;
  {{align-items}}: center;
  {{justify-content}}: center;
  {{background}}: linear-gradient(135deg, #f97316, #fbbf24);
  {{color}}: white;
  {{font-size}}: 32px;
  {{border-radius}}: 10px;
}
.track { {{height}}: 8px; margin: 12px 0; background: #eee; border-radius: 999px; overflow: hidden; }
.fill { {{width}}: 40%; height: 100%; background: #f97316; }
.lesson pre {
  {{background}}: #222;
  {{color}}: #fbbf24;
  {{padding}}: 12px;
  {{border-radius}}: 8px;
  {{font-size}}: 13px;
  {{overflow-x}}: auto;
}
.next {
  {{border}}: none;
  {{border-radius}}: 8px;
  {{background}}: #f97316;
  {{color}}: white;
  {{padding}}: 10px 18px;
  {{cursor}}: pointer;
}
